DECLARE @c CURSOR;
DECLARE @id int, @count int=0;
SET @c = CURSOR LOCAL FAST_FORWARD FOR SELECT OrderID FROM [retail].[Orders] WHERE 1=1 ORDER BY OrderID;
OPEN @c;
FETCH NEXT FROM @c INTO @id;
WHILE @@FETCH_STATUS=0
BEGIN
 SELECT @id AS OrderID;
 SET @count+=1;
 FETCH NEXT FROM @c INTO @id;
END;
CLOSE @c;
DEALLOCATE @c;
SELECT @count AS VisitedRows;
SELECT COUNT(*) AS SetBasedCount FROM [retail].[Orders] WHERE 1=1;

